import uuid

from fastapi import APIRouter, Depends, HTTPException, Query
from sqlalchemy.orm import Session

from src.backend.core.deps import get_current_user, require_role
from src.backend.core.roles import Role
from src.backend.db.session import get_db
from src.backend.models.user import User
from src.backend.schemas.task import (
    TaskCreate,
    TaskDependencyCreate,
    TaskListResponse,
    TaskRead,
    TaskStatusTransition,
    TaskUpdate,
)
from src.backend.services import task_service

router = APIRouter(prefix="/api", tags=["tasks"])


def _require_pm_or_admin():
    return require_role(Role.PM)


@router.get("/projects/{project_id}/tasks", response_model=TaskListResponse)
def list_project_tasks(
    project_id: uuid.UUID,
    _: User = Depends(get_current_user),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
    page: int = Query(default=1, ge=1),
    page_size: int = Query(default=20, ge=1, le=100),
    tree: bool = False,
    assignee_id: uuid.UUID | None = None,
) -> TaskListResponse:
    items, total = task_service.list_tasks_service(
        db, project_id, page=page, page_size=page_size, tree=tree, assignee_id=assignee_id
    )
    return TaskListResponse(items=items, total=total, page=page, page_size=page_size)


@router.post("/projects/{project_id}/tasks", response_model=TaskRead, status_code=201)
def create_task(
    project_id: uuid.UUID,
    body: TaskCreate,
    current_user: User = Depends(require_role(Role.PM)),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> TaskRead:
    try:
        task = task_service.create_task_service(db, project_id, body, current_user.id)
        return TaskRead.model_validate(task)
    except ValueError as e:
        raise HTTPException(status_code=400, detail=str(e)) from e


@router.get("/tasks/my", response_model=TaskListResponse)
def list_my_tasks(
    current_user: User = Depends(get_current_user),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
    page: int = Query(default=1, ge=1),
    page_size: int = Query(default=20, ge=1, le=100),
) -> TaskListResponse:
    items, total = task_service.list_my_tasks_service(db, current_user.id, page=page, page_size=page_size)
    return TaskListResponse(items=items, total=total, page=page, page_size=page_size)


@router.get("/tasks/{task_id}", response_model=TaskRead)
def get_task(
    task_id: uuid.UUID,
    _: User = Depends(get_current_user),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> TaskRead:
    task = task_service.get_task_service(db, task_id)
    if not task:
        raise HTTPException(status_code=404, detail="Task not found")
    return TaskRead.model_validate(task)


@router.patch("/tasks/{task_id}", response_model=TaskRead)
def update_task(
    task_id: uuid.UUID,
    body: TaskUpdate,
    current_user: User = Depends(require_role(Role.PM)),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> TaskRead:
    task = task_service.update_task_service(db, task_id, body, current_user.id)
    if not task:
        raise HTTPException(status_code=404, detail="Task not found")
    return TaskRead.model_validate(task)


@router.delete("/tasks/{task_id}", status_code=204)
def delete_task(
    task_id: uuid.UUID,
    current_user: User = Depends(require_role(Role.PM)),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> None:
    success = task_service.delete_task_service(db, task_id, current_user.id)
    if not success:
        raise HTTPException(status_code=404, detail="Task not found")


@router.post("/tasks/{task_id}/status", response_model=TaskRead)
def transition_task_status(
    task_id: uuid.UUID,
    body: TaskStatusTransition,
    current_user: User = Depends(require_role(Role.PM)),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> TaskRead:
    try:
        task = task_service.transition_task_status_service(db, task_id, body.status, current_user.id)
        return TaskRead.model_validate(task)
    except ValueError as e:
        raise HTTPException(status_code=409, detail=str(e)) from e


@router.post("/tasks/{task_id}/dependencies", response_model=TaskRead)
def add_task_dependency(
    task_id: uuid.UUID,
    body: TaskDependencyCreate,
    current_user: User = Depends(require_role(Role.PM)),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> TaskRead:
    try:
        task = task_service.add_dependency_service(db, task_id, body.depends_on_task_id, current_user.id)
        return TaskRead.model_validate(task)
    except ValueError as e:
        raise HTTPException(status_code=400, detail=str(e)) from e


@router.delete("/tasks/{task_id}/dependencies/{dependency_id}", status_code=204)
def remove_task_dependency(
